 function validate(d){normalize(d);FinanceHeads.validate(d);FinanceItems.validate(d);OtherIncome.validate(d);if(!Array.isArray(d.expenses))throw Error('Invalid expenses.');const ids=new Set();for(const b of d.branches)if(b.expenseSite&&!sites.includes(b.expenseSite))throw Error('Invalid branch expense location.');for(const e of d.expenses){validateRecord(e,d);if(ids.has(e.id)||!d.branches.some(b=>b.id===e.branchId)||!d.years[e.year])throw Error('Invalid expense branch, year or duplicate ID.');ids.add(e.id);}for(const x of d.deletedRecords||[])if(x.kind==='expense')validateRecord(x.expense,d);validateSalaryLinks(d);}
