// Non-student receipts remain separate from school fees and student dues.
const OtherIncome=(()=>{
 const heads=['Sublet rental income'];
 function valid(e,ledger=typeof data!=='undefined'?data:null){if(e?.masterItemId)FinanceItems.checkRecord(ledger,e,'income');if(e?.item!==undefined&&(typeof e.item!=='string'||e.item.length>200))throw Error('Invalid income item.');if(!e||!Admin.dateOK(e.date)||!Number.isFinite(e.amount)||e.amount<=0||!FinanceHeads.names('income',ledger).includes(e.head)||typeof e.payer!=='string'||!e.payer.trim()||e.payer.length>200||typeof e.narration!=='string'||e.narration.length>2000||!['Cash','UPI','Bank transfer','Cheque','Other'].includes(e.method)||typeof e.reference!=='string'||e.reference.length>100||!(/^[0-9a-f-]{36}$/i).test(e.id))throw Error('Enter a valid income date, positive amount, payer and payment details.');}
 function validate(d){if(!Array.isArray(d.otherIncomes))throw Error('Invalid other income records.');const ids=new Set();for(const e of d.otherIncomes){valid(e,d);if(ids.has(e.id)||!d.branches.some(b=>b.id===e.branchId)||!d.years[e.year])throw Error('Invalid other income branch, academic year or duplicate ID.');ids.add(e.id);}for(const x of d.deletedRecords||[])if(x.kind==='otherIncome')valid(x.otherIncome,d);}
 function changes(before,after){const out=[];for(const e of after.otherIncomes||[]){const old=(before.otherIncomes||[]).find(x=>x.id===e.id);if(JSON.stringify(old)!==JSON.stringify(e))out.push(History.event(after.datasetId,old?'Other income updated':'Other income recorded',e.head+' · '+e.payer,'Branch: '+after.branches.find(b=>b.id===e.branchId)?.name+'; Received: '+e.date+'; Amount: '+e.amount+'; '+e.narration,e.year));}for(const e of before.otherIncomes||[])if(!(after.otherIncomes||[]).some(x=>x.id===e.id))out.push(History.event(after.datasetId,'Other income deleted',e.head+' · '+e.payer,'Amount: '+e.amount,e.year));return out;}
 return{builtinHeads:heads,get heads(){return FinanceHeads.names('income',typeof data!=='undefined'?data:null);},valid,validate,changes};
})();
let otherIncomeEditing='',otherIncomeMonth='',otherIncomeSaving=false;
function otherIncomeRows(){return data.otherIncomes.filter(e=>(adminAllBranches||e.branchId===branchId)&&e.year===year&&(!otherIncomeMonth||e.date.startsWith(otherIncomeMonth))).sort((a,b)=>b.date.localeCompare(a.date));}
function renderOtherIncome(){if(otherIncomeEditing&&!data.otherIncomes.some(e=>e.id===otherIncomeEditing&&e.branchId===branchId&&e.year===year))otherIncomeEditing='';const rr=otherIncomeRows(),record=data.otherIncomes.find(e=>e.id===otherIncomeEditing&&e.branchId===branchId&&e.year===year)||{};return heading('Other income','Record non-student income separately from school fees. Amounts are included in income and expenditure reports.')+`<div class="toolbar"><label>Month received<input id="otherIncomeMonth" type="month" value="${esc(otherIncomeMonth)}"></label><button type="button" id="otherIncomeAllMonths">All months</button><button type="button" data-manage-heads="income">Manage heads &amp; items</button><button type="button" id="exportOtherIncome">Download income Excel</button></div><div class="card"><span>Other income received</span><strong>${money(rr.reduce((n,e)=>n+e.amount,0))}</strong><small>Selected branch, academic year and month · all classes</small></div>${adminAllBranches?'<p>Select a specific branch to record or edit income.</p>':`<div class="panel"><h2>${record.id?'Edit income':'Record income received'}</h2><form id="otherIncomeForm" novalidate><div class="grid"><label>Income head<select name="head">${OtherIncome.heads.filter(h=>FinanceHeads.available(data,'income',h,record.head)).map(h=>FinanceHeads.option('income',h,h===record.head)).join('')}</select></label><div id="otherIncomeItemFields">${FinanceItems.selector('income',record.head||FinanceHeads.active('income',data)[0]||'',branchId,record.masterItemId)}</div>${field('date','Date received *','date',record.date||today(),'required')}${field('amount','Amount received *','number',record.amount??'','required min="0.01" step="0.01"')}${field('payer','Received from / tenant *','text',record.payer||'','required maxlength="200"')}<label>Payment method<select name="method">${['Cash','UPI','Bank transfer','Cheque','Other'].map(m=>`<option ${record.method===m?'selected':''}>${m}</option>`).join('')}</select></label>${field('reference','Receipt / reference','text',record.reference||'','maxlength="100"')}<label>Narration<textarea name="narration" maxlength="2000" placeholder="Rental period, premises or other details">${esc(record.narration||'')}</textarea></label></div><div class="collection-save-actions"><button type="button" id="saveOtherIncome" class="primary">Save income</button><span id="otherIncomeMessage" role="status" aria-live="polite"></span></div>${record.id?'<button type="button" id="cancelOtherIncomeEdit">Cancel edit</button>':''}</form></div>`}<div class="panel"><h2>Other income history</h2><div id="otherIncomeHistoryMessage" role="status" aria-live="polite"></div>${table(['Branch','Date received','Income head','Item','Received from','Narration','Amount','Method','Reference','Actions'],rr.map(e=>`<tr><td>${esc(data.branches.find(b=>b.id===e.branchId)?.name)}</td><td>${esc(e.date)}</td><td>${esc(FinanceHeads.label('income',e.head))}</td><td>${esc(e.item||'')}</td><td>${esc(e.payer)}</td><td>${esc(e.narration)}</td><td>${money(e.amount)}</td><td>${esc(e.method)}</td><td>${esc(e.reference)}</td><td>${adminAllBranches?'':`<button type="button" data-income-edit="${e.id}">Edit</button><button type="button" class="danger" data-income-delete="${e.id}">Delete</button>`}</td></tr>`).join(''))}</div>`;}
function otherIncomeFeedback(message){const node=$('#otherIncomeMessage')||$('#otherIncomeHistoryMessage');if(node)node.textContent=message;notice(message);}
function bindOtherIncome(){if(tab!=='otherincome')return;const form=$('#otherIncomeForm');$('#otherIncomeForm [name=head]')?.addEventListener('change',e=>{$('#otherIncomeItemFields').innerHTML=FinanceItems.selector('income',e.target.value,branchId);});if(form)form.incomeScope={branchId,year,id:otherIncomeEditing,record:JSON.stringify(data.otherIncomes.find(e=>e.id===otherIncomeEditing)||null)};$('#otherIncomeMonth')?.addEventListener('change',e=>{otherIncomeMonth=e.target.value;render();});$('#otherIncomeAllMonths')?.addEventListener('click',()=>{otherIncomeMonth='';render();});$('#cancelOtherIncomeEdit')?.addEventListener('click',()=>{otherIncomeEditing='';render();});$('#saveOtherIncome')?.addEventListener('click',saveOtherIncome);form?.addEventListener('submit',e=>{e.preventDefault();saveOtherIncome();});$('#exportOtherIncome')?.addEventListener('click',()=>{if(TeacherProfile.teacher())return notice('Administrator access required.');const rr=otherIncomeRows();download(makeWorkbook({'Other income':[['Branch','Academic year','Date received','Income head','Received from','Narration','Amount','Method','Reference','Item'],...rr.map(e=>[data.branches.find(b=>b.id===e.branchId)?.name,e.year,e.date,FinanceHeads.label('income',e.head),e.payer,e.narration,e.amount,e.method,e.reference,e.item||'']),['Total','','','','','',cents(rr.reduce((n,e)=>n+e.amount,0))]]}),'little-wings-other-income-'+today()+'.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');});}
async function saveOtherIncome(){if(otherIncomeSaving)return false;otherIncomeFeedback('Checking income…');const button=$('#saveOtherIncome');try{if(TeacherProfile.teacher())throw Error('Sign in as administrator.');if(adminAllBranches||currentBranch().archived)throw Error('Select an active branch to record income.');const form=$('#otherIncomeForm'),scope=form?.incomeScope;if(!scope||scope.branchId!==branchId||scope.year!==year)throw Error('Branch or year changed. Reopen the income form.');const old=data.otherIncomes.find(e=>e.id===scope.id);if(JSON.stringify(old||null)!==scope.record)throw Error('This income changed. Reopen the form.');if(old&&(old.branchId!==branchId||old.year!==year))throw Error('Reopen income in its branch and year.');const f=new FormData(form),master=FinanceItems.select(data,String(f.get('masterItemId')||''),'income',String(f.get('head')||''),branchId,old?.masterItemId),record={id:old?.id||uid(),branchId,year,head:String(f.get('head')||''),date:String(f.get('date')||''),amount:cents(Number(f.get('amount'))),payer:String(f.get('payer')||'').trim(),narration:String(f.get('narration')||'').trim(),method:String(f.get('method')||'Cash'),reference:String(f.get('reference')||'').trim()};if(!FinanceHeads.available(data,'income',record.head,old?.head))throw Error('Select an active income head.');if(master){record.masterItemId=master.id;record.item=master.name;}OtherIncome.valid(record);const next=clone(),i=next.otherIncomes.findIndex(e=>e.id===record.id);if(i<0)next.otherIncomes.push(record);else next.otherIncomes[i]=record;otherIncomeSaving=true;button.disabled=true;button.textContent='Saving…';otherIncomeFeedback('Saving income…');let failure;const ok=await commit(next,{quiet:true,onError:e=>{failure=e;}});if(!ok)throw failure||Error('Income was not saved.');otherIncomeEditing='';if(otherIncomeMonth&&!record.date.startsWith(otherIncomeMonth))otherIncomeMonth='';try{render();}catch(e){otherIncomeEditing=record.id;if(form)form.incomeScope={branchId:record.branchId,year:record.year,id:record.id,record:JSON.stringify(record)};otherIncomeFeedback('Income saved. Refresh to update the history.');return true;}otherIncomeFeedback('Income saved successfully.');return true;}catch(error){otherIncomeFeedback('Not saved: '+error.message);return false;}finally{otherIncomeSaving=false;const b=$('#saveOtherIncome');if(b){b.disabled=false;b.textContent='Save income';}}}
async function otherIncomeClick(button){if(!button.dataset.incomeEdit&&!button.dataset.incomeDelete)return;try{if(otherIncomeSaving)throw Error('Wait for the current income save.');if(TeacherProfile.teacher()||adminAllBranches||currentBranch().archived)throw Error('Select an active branch as administrator.');const e=data.otherIncomes.find(e=>e.id===(button.dataset.incomeEdit||button.dataset.incomeDelete)&&e.branchId===branchId&&e.year===year);if(!e)throw Error('Income record not found in this branch and year.');if(button.dataset.incomeEdit){otherIncomeEditing=e.id;render();return;}if(!await AppDialogs.confirm('Delete this income receipt? It can be restored from Activity history.'))return;const next=clone();next.otherIncomes=next.otherIncomes.filter(x=>x.id!==e.id);next.deletedRecords.push({id:uid(),kind:'otherIncome',deletedAt:new Date().toISOString(),otherIncome:structuredClone(e),year:e.year});otherIncomeSaving=true;button.disabled=true;otherIncomeFeedback('Deleting income…');let failure;const ok=await commit(next,{quiet:true,onError:e=>failure=e});if(!ok)throw failure||Error('Income not deleted.');otherIncomeEditing='';render();otherIncomeFeedback('Income deleted. It can be restored in Activity history.');}catch(error){otherIncomeFeedback(error.message);}finally{otherIncomeSaving=false;button.disabled=false;}}

const FinanceItems=(()=>{
 const headFor=(kind,d=typeof data!=='undefined'?data:null)=>FinanceHeads.names(kind,d);
 function validate(d){if(!Array.isArray(d.financeItems))throw Error('Invalid expense / income items master.');const ids=new Set(),seen=[];for(const item of d.financeItems){if(!item||!(/^[0-9a-f-]{36}$/i).test(item.id)||ids.has(item.id)||!headFor(item.kind,d).includes(item.head)||typeof item.name!=='string'||!item.name.trim()||item.name!==item.name.trim()||item.name.length>200||typeof item.archived!=='boolean'||!(item.branchId==='ALL'||d.branches.some(b=>b.id===item.branchId)||(d.deletedRecords||[]).some(x=>x.kind==='branch'&&x.branch.id===item.branchId)))throw Error('Invalid finance item, head or branch.');if(seen.some(x=>x.kind===item.kind&&x.head===item.head&&x.name.toLocaleLowerCase()===item.name.toLocaleLowerCase()&&(x.branchId===item.branchId||x.branchId==='ALL'||item.branchId==='ALL')))throw Error('An item with this name already exists under this head and branch scope. Restore the existing item if archived.');seen.push(item);ids.add(item.id);}}
 function select(d,id,kind,head,branch,previous){if(!id)return null;const item=(d?.financeItems||[]).find(x=>x.id===id&&x.kind===kind&&x.head===head&&(x.branchId==='ALL'||x.branchId===branch));if(!item||item.archived&&previous!==id)throw Error('Select an active master item for this head and branch.');return item;}
 function checkRecord(d,e,kind){const item=(d?.financeItems||[]).find(x=>x.id===e.masterItemId);if(!item||item.kind!==kind||item.head!==(kind==='expense'?e.category:e.head)||(item.branchId!=='ALL'&&item.branchId!==e.branchId)||item.name!==(kind==='expense'?e.subhead:e.item))throw Error('The saved expense / income item does not match its master, head or branch.');return item;}
 function used(d,id){const scan=v=>v&&typeof v==='object'&&(v.masterItemId===id||Object.values(v).some(x=>Array.isArray(x)?x.some(scan):x&&typeof x==='object'?scan(x):false));return [...d.expenses,...d.otherIncomes,...d.deletedRecords].some(scan);}
 function selector(kind,head,branch,selected=''){const items=(data.financeItems||[]).filter(x=>x.kind===kind&&x.head===head&&(x.branchId==='ALL'||x.branchId===branch)&&(!x.archived||x.id===selected));return `<label>Item from master (optional)<select name="masterItemId"><option value="">Use standard fields / no master item</option>${items.map(x=>`<option value="${x.id}" ${x.id===selected?'selected':''}>${esc(x.name)}${x.archived?' (archived)':''}</option>`).join('')}</select></label><small>Items can be added under Admin → Expense &amp; income masters.</small>`;}
 function changes(before,after){const out=[];for(const item of after.financeItems||[]){const old=(before.financeItems||[]).find(x=>x.id===item.id);if(JSON.stringify(old)!==JSON.stringify(item))out.push(History.event(after.datasetId,!old?'Finance master item created':item.archived?'Finance master item archived':'Finance master item restored',item.head+' · '+item.name,'Type: '+item.kind+'; Scope: '+(item.branchId==='ALL'?'All branches':after.branches.find(b=>b.id===item.branchId)?.name||'Deleted branch')));}for(const item of before.financeItems||[])if(!(after.financeItems||[]).some(x=>x.id===item.id))out.push(History.event(after.datasetId,'Unused finance master item deleted',item.head+' · '+item.name));return out;}
 return{headFor,validate,select,checkRecord,used,selector,changes};
})();
let financeItemSaving=false,financeItemDraft=null;
function renderFinanceItems(){return heading('Expense & income masters','Create heads and items for expenses or other income. Heads are shared across branches; items can be limited to one branch.')+financeHeadMarkup()+`<button type="button" id="exportFinanceItems">Download master Excel</button><section class="panel"><h2>Create item</h2><form id="financeItemForm" novalidate><div class="grid"><label>Module<select name="kind" id="financeItemKind"><option value="expense">Expenses</option><option value="income">Other income</option></select></label><label>Head<select name="head" id="financeItemHead">${FinanceHeads.active('expense',data).map(h=>FinanceHeads.option('expense',h)).join('')}</select></label><label>Item name *<input name="name" required maxlength="200" placeholder="Shop, vendor, service or other item"></label><label>Available in<select name="branchId"><option value="ALL">ALL branches</option>${data.branches.filter(b=>!b.archived).map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></label></div><div class="collection-save-actions"><button type="submit" id="saveFinanceItem" class="primary">Create item</button><span id="financeItemMessage" role="status" aria-live="polite"></span></div></form></section><section class="panel"><h2>Saved items</h2><p>Items become available when recording expenses or other income. Archive an item to stop new use; saved receipts keep the item name. Only unused items can be deleted. Existing built-in shop and subscription choices remain available.</p>${table(['Module','Head','Item','Branch scope','Status','Actions'],(data.financeItems||[]).map(item=>`<tr><td>${item.kind==='expense'?'Expenses':'Other income'}</td><td>${esc(FinanceHeads.label(item.kind,item.head))}</td><td>${esc(item.name)}</td><td>${item.branchId==='ALL'?'ALL branches':esc(data.branches.find(b=>b.id===item.branchId)?.name||'Deleted branch')}</td><td>${item.archived?'Archived':'Active'}</td><td><button type="button" data-finance-archive="${item.id}">${item.archived?'Restore':'Archive'}</button>${FinanceItems.used(data,item.id)?'':'<button type="button" class="danger" data-finance-delete="'+item.id+'">Delete unused item</button>'}</td></tr>`).join(''))}</section>`;}
function financeItemFeedback(text){const node=$('#financeItemMessage');if(node)node.textContent=text;notice(text);}
function bindFinanceItems(){if(tab!=='financemasters')return;bindFinanceHeads();$('#exportFinanceItems')?.addEventListener('click',downloadFinanceItems);$('#financeItemKind')?.addEventListener('change',e=>{$('#financeItemHead').innerHTML=FinanceHeads.active(e.target.value,data).map(h=>FinanceHeads.option(e.target.value,h)).join('');});$('#financeItemForm')?.addEventListener('submit',saveFinanceItem);}
async function saveFinanceItem(event){event.preventDefault();if(financeItemSaving||financeHeadSaving||financeHeadNameSaving)return false;const button=$('#saveFinanceItem');try{if(TeacherProfile.teacher())throw Error('Only the administrator can maintain finance items.');const f=new FormData(event.target),fields={kind:String(f.get('kind')||''),head:String(f.get('head')||''),name:String(f.get('name')||'').trim(),branchId:String(f.get('branchId')||'')};if(fields.branchId!=='ALL'&&!data.branches.some(b=>b.id===fields.branchId&&!b.archived))throw Error('Select ALL branches or an active branch.');if(!FinanceHeads.available(data,fields.kind,fields.head))throw Error('Select an active head before creating an item.');const signature=JSON.stringify(fields);if(!financeItemDraft||financeItemDraft.signature!==signature||financeItemDraft.base!==recordContent(data))financeItemDraft={id:uid(),signature,base:recordContent(data)};const next=clone();next.financeItems.push({id:financeItemDraft.id,...fields,archived:false});FinanceItems.validate(next);financeItemSaving=true;button.disabled=true;financeItemFeedback('Saving master item…');let failure;if(!await commit(next,{quiet:true,onError:e=>failure=e}))throw failure||Error('Master item was not saved.');financeItemDraft=null;try{render();}catch(error){financeItemFeedback('Item saved. Refresh to update the master list.');return true;}financeItemFeedback('Master item created. It is available under '+FinanceHeads.label(fields.kind,fields.head)+'.');return true;}catch(error){financeItemFeedback(error.message);return false;}finally{financeItemSaving=false;const b=$('#saveFinanceItem');if(b)b.disabled=false;}}
async function financeItemClick(button){const id=button.dataset.financeArchive||button.dataset.financeDelete;if(!id)return;try{if(TeacherProfile.teacher())throw Error('Only the administrator can maintain finance items.');if(financeItemSaving||financeHeadSaving||financeHeadNameSaving)throw Error('Wait for the current master save.');const next=clone(),item=next.financeItems.find(x=>x.id===id);if(!item)throw Error('This master item no longer exists.');if(button.dataset.financeDelete){if(FinanceItems.used(next,id))throw Error('This item is used by saved or deleted receipts. Archive it instead.');if(!await AppDialogs.confirm('Delete this unused master item?'))return;next.financeItems=next.financeItems.filter(x=>x.id!==id);}else item.archived=!item.archived;financeItemSaving=true;button.disabled=true;let failure;if(!await commit(next,{quiet:true,onError:e=>failure=e}))throw failure||Error('Master update was not saved.');render();financeItemFeedback('Master item updated.');}catch(error){financeItemFeedback(error.message);}finally{financeItemSaving=false;button.disabled=false;}}

function downloadFinanceItems(){if(TeacherProfile.teacher())return notice('Administrator access required.');download(makeWorkbook({'Finance heads':[['Module','Head','Type','Status'],...['expense','income'].flatMap(kind=>FinanceHeads.names(kind,data).map(name=>[kind==='expense'?'Expenses':'Other income',FinanceHeads.label(kind,name),FinanceHeads.builtin(kind).includes(name)?'Built-in':'Custom',FinanceHeads.available(data,kind,name)?'Active':'Archived']))],'Expense & income items':[['Module','Head','Item','Branch scope','Status'],...data.financeItems.map(item=>[item.kind==='expense'?'Expenses':'Other income',FinanceHeads.label(item.kind,item.head),item.name,item.branchId==='ALL'?'ALL branches':data.branches.find(b=>b.id===item.branchId)?.name||'Deleted branch',item.archived?'Archived':'Active'])]}),'little-wings-finance-items-'+today()+'.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');}

const FinanceHeads=(()=>{
 const label=(kind,head,d=typeof data!=='undefined'?data:null)=>(d?.financeHeadLabels||[]).find(x=>x.kind===kind&&x.head===head)?.label||head;
 const option=(kind,head,selected=false)=>`<option value="${esc(head)}" ${selected?'selected':''}>${esc(label(kind,head))}</option>`;
 const builtin=kind=>kind==='expense'?Expenses.builtinCategories:kind==='income'?OtherIncome.builtinHeads:[];
 function names(kind,d){return [...builtin(kind),...(d?.financeHeads||[]).filter(h=>h.kind===kind).map(h=>h.name)];}
 function available(d,kind,name,previous){return builtin(kind).includes(name)||(d?.financeHeads||[]).some(h=>h.kind===kind&&h.name===name&&(!h.archived||name===previous));}
 function active(kind,d){return names(kind,d).filter(name=>available(d,kind,name));}
 function validate(d){if(!Array.isArray(d.financeHeads))throw Error('Invalid finance head master.');const ids=new Set(),seen={expense:new Set(builtin('expense').map(x=>x.toLowerCase())),income:new Set(builtin('income').map(x=>x.toLowerCase()))},reserved=new Set(['school','totalincome','totalexpenses','net','school fees','annual day fees','picnic fees','sports day fees']);for(const head of d.financeHeads){if(!head||!['expense','income'].includes(head.kind)||!(/^[0-9a-f-]{36}$/i).test(head.id)||ids.has(head.id)||typeof head.name!=='string'||!head.name.trim()||head.name!==head.name.trim()||head.name.length>120||typeof head.archived!=='boolean')throw Error('Enter a valid module and head name (up to 120 characters).');const key=head.name.toLowerCase();if(seen[head.kind].has(key))throw Error('This head already exists in the selected module. Restore it if archived.');if(reserved.has(key))throw Error('This name is reserved for student collections or report totals. Choose another head name.');seen[head.kind].add(key);ids.add(head.id);}validateLabels(d);}
 function validateLabels(d){if(!Array.isArray(d.financeHeadLabels))throw Error('Invalid head names.');const keys=new Set();for(const row of d.financeHeadLabels){const key=row.kind+'|'+row.head;if(!['expense','income'].includes(row.kind)||!names(row.kind,d).includes(row.head)||keys.has(key)||typeof row.label!=='string'||!row.label.trim()||row.label!==row.label.trim()||row.label.length>120)throw Error('Enter a valid head name up to 120 characters.');keys.add(key);}for(const kind of ['expense','income']){const seen=new Set();for(const head of names(kind,d)){const name=label(kind,head,d).toLowerCase();if(seen.has(name))throw Error('This head name already exists in the selected module. Choose a different name.');seen.add(name);}}}
 function changes(before,after){const out=[];for(const row of after.financeHeadLabels||[]){const old=label(row.kind,row.head,before);if(old!==row.label)out.push(History.event(after.datasetId,'Finance head renamed',old+' → '+row.label,'Module: '+row.kind+'; applies to saved records and reports.'));}for(const h of after.financeHeads||[]){const old=(before.financeHeads||[]).find(x=>x.id===h.id);if(JSON.stringify(old)!==JSON.stringify(h))out.push(History.event(after.datasetId,!old?'Finance head created':h.archived?'Finance head archived':'Finance head restored',h.name,'Module: '+h.kind+'; available across all branches.'));}return out;}
 return{label,option,builtin,names,active,available,validate,changes};
})();
let financeHeadSaving=false,financeHeadDraft=null;
function financeHeadMarkup(){return `<section class="panel"><h2>Create head</h2><p>New heads are available for all branches. You can add items under them using Create item below. Archiving stops new use while keeping existing receipts and reports.</p><form id="financeHeadForm" novalidate><div class="grid"><label>Module<select name="kind"><option value="expense">Expenses</option><option value="income">Other income</option></select></label><label>Head name *<input name="name" required maxlength="120" placeholder="Enter a new expense or income head"></label></div><div class="collection-save-actions"><button type="submit" id="saveFinanceHead" class="primary">Create head</button><span id="financeHeadMessage" role="status" aria-live="polite"></span></div></form>${financeHeadNameMarkup()}${'<h3>All heads</h3>'+table(['Module','Head','Status','Actions'],['expense','income'].flatMap(kind=>FinanceHeads.names(kind,data).map(name=>{const custom=data.financeHeads.find(h=>h.kind===kind&&h.name===name);return `<tr><td>${kind==='expense'?'Expenses':'Other income'}</td><td>${esc(FinanceHeads.label(kind,name))}</td><td>${custom?.archived?'Archived':'Active'}</td><td><button type="button" data-head-rename="${esc(name)}" data-head-kind="${kind}">Edit name</button>${custom?`<button type="button" data-head-archive="${custom.id}">${custom.archived?'Restore':'Archive'}</button>`:''}</td></tr>`;})).join(''))}</section>`;}
function financeHeadFeedback(message){const el=$('#financeHeadMessage');if(el)el.textContent=message;notice(message);}
function bindFinanceHeads(){bindFinanceHeadNames();$('#financeHeadForm')?.addEventListener('submit',saveFinanceHead);}
async function saveFinanceHead(event){event.preventDefault();if(financeHeadSaving||financeItemSaving||financeHeadNameSaving)return false;const button=$('#saveFinanceHead');try{if(TeacherProfile.teacher())throw Error('Only the administrator can create finance heads.');const f=new FormData(event.target),kind=String(f.get('kind')||''),name=String(f.get('name')||'').trim(),signature=JSON.stringify([kind,name]);if(!financeHeadDraft||financeHeadDraft.signature!==signature||financeHeadDraft.base!==recordContent(data))financeHeadDraft={id:uid(),signature,base:recordContent(data)};const next=clone();next.financeHeads.push({id:financeHeadDraft.id,kind,name,archived:false});FinanceHeads.validate(next);financeHeadSaving=true;button.disabled=true;financeHeadFeedback('Saving new head…');let failure;if(!await commit(next,{quiet:true,onError:e=>failure=e}))throw failure||Error('Head was not saved.');financeHeadDraft=null;try{render();}catch(error){financeHeadFeedback('Head saved. Refresh to update the list.');return true;}financeHeadFeedback('Head created: '+name+'. Select it when recording '+(kind==='expense'?'expenses':'other income')+' or creating items.');return true;}catch(error){financeHeadFeedback(error.message);return false;}finally{financeHeadSaving=false;const b=$('#saveFinanceHead');if(b)b.disabled=false;}}
async function financeHeadClick(button){if(button.dataset.headRename){openFinanceHeadName(button.dataset.headKind,button.dataset.headRename);return;}if(!button.dataset.headArchive)return;try{if(TeacherProfile.teacher())throw Error('Administrator access required.');if(financeHeadSaving||financeItemSaving||financeHeadNameSaving)throw Error('Wait for the current master save.');const next=clone(),head=next.financeHeads.find(h=>h.id===button.dataset.headArchive);if(!head)throw Error('Head not found.');head.archived=!head.archived;financeHeadSaving=true;button.disabled=true;let failure;if(!await commit(next,{quiet:true,onError:e=>failure=e}))throw failure||Error('Head update was not saved.');render();financeHeadFeedback('Head '+(head.archived?'archived. Existing records are retained.':'restored.'));}catch(error){financeHeadFeedback(error.message);}finally{financeHeadSaving=false;button.disabled=false;}}

function openFinanceHeads(kind){if(TeacherProfile.teacher())return notice('Administrator access required.');if(!['expense','income'].includes(kind))return;navigateTo('financemasters');$('#financeHeadForm [name=kind]').value=kind;$('#financeItemKind').value=kind;$('#financeItemHead').innerHTML=FinanceHeads.active(kind,data).map(h=>FinanceHeads.option(kind,h)).join('');}

let financeHeadNameSaving=false;
function financeHeadNameMarkup(){return `<div class="panel"><h3>Edit head name</h3><p>Names can be changed for built-in and custom heads. The updated name appears on saved entries, items and reports. Salary, branch and collection rules continue to apply.</p><form id="financeHeadNameForm" novalidate><div class="grid"><label>Module<select name="kind" id="renameHeadKind"><option value="expense">Expenses</option><option value="income">Other income</option></select></label><label>Head<select name="head" id="renameHeadKey">${FinanceHeads.names('expense',data).map(h=>FinanceHeads.option('expense',h)).join('')}</select></label><label>New head name *<input name="label" id="renameHeadLabel" maxlength="120" required value="${esc(FinanceHeads.label('expense',Expenses.builtinCategories[0]))}"></label></div><div class="collection-save-actions"><button type="submit" id="saveFinanceHeadName" class="primary">Save head name</button><span id="financeHeadNameMessage" role="status" aria-live="polite"></span></div></form></div>`;}
function headNameFeedback(message){const node=$('#financeHeadNameMessage');if(node)node.textContent=message;notice(message);}
function openFinanceHeadName(kind,head){if(TeacherProfile.teacher())return notice('Administrator access required.');if(!FinanceHeads.names(kind,data).includes(head))return headNameFeedback('Head no longer exists. Reload the master.');$('#renameHeadKind').value=kind;$('#renameHeadKey').innerHTML=FinanceHeads.names(kind,data).map(h=>FinanceHeads.option(kind,h,h===head)).join('');$('#renameHeadKey').value=head;const label=FinanceHeads.label(kind,head);$('#renameHeadLabel').value=label;$('#financeHeadNameForm').expectedHeadName={kind,head,label};$('#renameHeadLabel').scrollIntoView?.({block:'center'});}
function bindFinanceHeadNames(){const form=$('#financeHeadNameForm');if(!form)return;const remember=()=>{const kind=$('#renameHeadKind').value||'expense',head=$('#renameHeadKey').value||FinanceHeads.names(kind,data)[0],label=FinanceHeads.label(kind,head);$('#renameHeadLabel').value=label;form.expectedHeadName={kind,head,label};};$('#renameHeadKind')?.addEventListener('change',e=>{$('#renameHeadKey').innerHTML=FinanceHeads.names(e.target.value,data).map(h=>FinanceHeads.option(e.target.value,h)).join('');remember();});$('#renameHeadKey')?.addEventListener('change',remember);form.expectedHeadName={kind:'expense',head:Expenses.builtinCategories[0],label:FinanceHeads.label('expense',Expenses.builtinCategories[0])};form.addEventListener('submit',saveFinanceHeadName);}
async function saveFinanceHeadName(event){event.preventDefault();if(financeHeadNameSaving||financeHeadSaving||financeItemSaving)return false;const button=$('#saveFinanceHeadName');try{if(TeacherProfile.teacher())throw Error('Only the administrator can edit head names.');const f=new FormData(event.target),kind=String(f.get('kind')||''),head=String(f.get('head')||''),label=String(f.get('label')||'').trim();if(!FinanceHeads.names(kind,data).includes(head))throw Error('Select a valid head.');const old=FinanceHeads.label(kind,head),expected=event.target.expectedHeadName;if(expected&&(expected.kind!==kind||expected.head!==head||expected.label!==old))throw Error('This head changed. Select it again to review its latest name.');if(label===old){headNameFeedback('Head name is unchanged.');return true;}const next=clone(),row=next.financeHeadLabels.find(x=>x.kind===kind&&x.head===head);if(row)row.label=label;else next.financeHeadLabels.push({kind,head,label});FinanceHeads.validate(next);financeHeadNameSaving=true;button.disabled=true;headNameFeedback('Saving head name…');let failure;if(!await commit(next,{quiet:true,onError:e=>failure=e}))throw failure||Error('Head name was not saved.');try{render();}catch(error){headNameFeedback('Head name saved. Refresh to update the screen.');return true;}headNameFeedback('Head renamed: '+old+' → '+label+'. Saved records and reports use the new name.');return true;}catch(error){headNameFeedback(error.message);return false;}finally{financeHeadNameSaving=false;const b=$('#saveFinanceHeadName');if(b)b.disabled=false;}}
